<script setup>
import {computed,reactive,ref,watch} from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue';
import {toAdminUserDraft,toAdminUserPayload} from '../domain/admin-user-write.mjs';
const props=defineProps({record:Object,editing:Boolean,saving:Boolean,error:String,roleOptions:{type:Array,default:()=>[]}});const emit=defineEmits(['cancel','save']);const draft=reactive({...toAdminUserDraft(props.record)});const localError=ref('');const title=computed(()=>props.editing?'Sửa người dùng':'Thêm người dùng');watch(()=>props.record,(record)=>Object.assign(draft,toAdminUserDraft(record)),{deep:true});const states=[{value:true,label:'Hoạt động'},{value:false,label:'Khóa'}];const notifications=[{value:true,label:'Nhận nhắc'},{value:false,label:'Không nhận nhắc'}];function submit(){try{localError.value='';emit('save',toAdminUserPayload(draft,{editing:props.editing}));}catch(error){localError.value=error.message;}}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[720px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">{{ title }}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Phân quyền được máy chủ kiểm tra lại khi lưu.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label v-if="!editing"><span class="mb-1 block text-[13px] font-medium">Tài khoản *</span><MInput v-model="draft.username" :disabled="saving" autocomplete="username"/></label><label :class="editing?'sm:col-span-2':''"><span class="mb-1 block text-[13px] font-medium">Họ tên *</span><MInput v-model="draft.full_name" :disabled="saving" autocomplete="name"/></label><label><span class="mb-1 block text-[13px] font-medium">Vai trò *</span><MSelect v-model="draft.role" :options="roleOptions" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Email</span><MInput v-model="draft.email" type="email" :disabled="saving" autocomplete="email"/></label><label><span class="mb-1 block text-[13px] font-medium">{{ editing?'Mật khẩu mới':'Mật khẩu *' }}</span><MInput v-model="draft.password" type="password" :disabled="saving" :placeholder="editing?'Để trống nếu không đổi':''" :autocomplete="editing?'new-password':'new-password'"/></label><template v-if="editing"><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.active" :options="states" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Nhắc việc</span><MSelect v-model="draft.notify_opt_in" :options="notifications" :disabled="saving"/></label></template></div><p v-if="error||localError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error||localError }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" @click="submit">{{ editing?'Lưu thay đổi':'Tạo người dùng' }}</MButton></footer></form></section></template>
